(() => {
  // 详情页数据可拆成独立 component registry；示例重点展示可扩展的章节结构。
  const formSections = [
    { id: 'text', title: '文本输入', description: '普通、长文本、错误与禁用。', markup: `<div class="variant-grid"><section class="variant"><h3>默认</h3><p>短文本输入。</p><label class="field">名称<input value="示例原型"></label></section><section class="variant"><h3>Error</h3><p>错误文字紧跟字段。</p><label class="field">仓库<input aria-invalid="true" value="unknown/repo"></label><span class="pill danger">找不到该仓库</span></section></div>` },
    { id: 'selects', title: '选择器', description: '选项规模和选择模式分别建模。', markup: `<div class="variant-grid"><section class="variant"><h3>单选</h3><p>少量选项。</p><label class="field">模块<select><option>Core</option><option>Settings</option></select></label></section><section class="variant"><h3>多选</h3><p>已选内容使用 Token。</p><span class="pill">Core ×</span> <span class="pill">Settings ×</span></section><section class="variant"><h3>可搜索</h3><p>大量选项。</p><label class="field">搜索<input placeholder="搜索选项…"></label></section><section class="variant"><h3>异步加载</h3><p>显示加载与空状态。</p><label class="field">远程选项<input value="正在加载…" disabled></label></section><section class="variant"><h3>级联</h3><p>先确定上级范围。</p><label class="field">项目<select><option>Project A</option></select></label><label class="field">模块<select><option>Module B</option></select></label></section><section class="variant"><h3>禁用与空状态</h3><p>解释不可用原因。</p><label class="field">模块<select disabled><option>请先选择项目</option></select></label></section></div>` },
    { id: 'choices', title: '勾选与开关', description: '区分多选、单选与即时设置。', markup: `<div class="variant-grid"><section class="variant"><h3>Checkbox</h3><label><input type="checkbox" checked> 选项 A</label><br><label><input type="checkbox"> 选项 B</label></section><section class="variant"><h3>Radio</h3><label><input type="radio" name="mode" checked> 模式 A</label><br><label><input type="radio" name="mode"> 模式 B</label></section><section class="variant"><h3>Switch</h3><label><input type="checkbox" role="switch" checked> 启用设置</label></section><section class="variant"><h3>日期时间</h3><label class="field">更新时间<input type="datetime-local"></label></section></div>` },
    { id: 'states', title: '状态矩阵', description: '每个正式组件都应覆盖相关通用状态。', markup: `<table class="state-table"><thead><tr><th>状态</th><th>视觉</th><th>交互</th></tr></thead><tbody><tr><td>Default</td><td>边界清晰</td><td>鼠标与键盘可用</td></tr><tr><td>Focus</td><td>可见焦点环</td><td>顺序合理</td></tr><tr><td>Loading</td><td>保持尺寸</td><td>避免重复提交</td></tr><tr><td>Error</td><td>错误文字</td><td>说明恢复动作</td></tr><tr><td>Disabled</td><td>降低对比</td><td>不可触发</td></tr><tr><td>Empty</td><td>说明无结果</td><td>允许重试</td></tr></tbody></table>` },
  ];
  const definitions = {
    forms: { title: '表单与选择', category: 'Inputs', code: 'Input · Select · Choice', description: '按类型、选项规模和状态拆分表单变体。', sections: formSections },
    buttons: { title: '按钮', category: 'Actions', code: 'Button', description: '操作层级、尺寸与状态。', sections: ['层级与语义','尺寸','Loading 与 Disabled'] },
    table: { title: '表格', category: 'Data display', code: 'Table', description: '扫描、选择、排序与空状态。', sections: ['基础表格','行选择','Loading 与 Empty'] },
    feedback: { title: '反馈与浮层', category: 'Feedback', code: 'Dialog · Toast', description: '操作结果与高风险确认。', sections: ['Dialog','Toast','Loading 与 Error'] },
  };
  const key = new URLSearchParams(location.search).get('component') || 'forms'; const definition = definitions[key] || definitions.forms;
  const sections = Array.isArray(definition.sections[0]) || typeof definition.sections[0] === 'object' ? definition.sections : definition.sections.map((title,index) => ({ id: `variant-${index+1}`, title, description: '替换为组件变体说明。', markup: `<div class="variant"><span class="pill">示例</span> ${title}</div>` }));
  document.querySelector('#detail-title').textContent = definition.title; document.querySelector('#detail-category').textContent = definition.category; document.querySelector('#detail-description').textContent = definition.description; document.querySelector('#detail-code').textContent = definition.code;
  document.querySelector('#detail-nav').innerHTML = sections.map((section) => `<a href="#${section.id}">${section.title}</a>`).join(''); document.querySelector('#detail-content').innerHTML = sections.map((section) => `<section id="${section.id}" class="detail-section"><h2>${section.title}</h2><p>${section.description}</p>${section.markup}</section>`).join('');
})();
